diff --git a/libs/traffichistory.cpp b/libs/traffichistory.cpp
new file mode 100644
index 000000000..51b34a1df
--- /dev/null
+++ b/libs/traffichistory.cpp
@@ -0,0 +1,114 @@
+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: LGPL-2.1-only OR LGPL-3.0-only OR LicenseRef-KDE-Accepted-LGPL
+*/
+
+#include "traffichistory.h"
+
+#include <QFile>
+
+#include <NetworkManagerQt/Manager>
+
+using namespace Qt::StringLiterals;
+
+static constexpr int s_interval = 2000;
+static constexpr int s_historyLength = 40;
+
+static bool readCounter(const QString &path, quint64 *value)
+{
+    QFile file(path);
+    if (!file.open(QIODevice::ReadOnly)) {
+        return false;
+    }
+    bool ok = false;
+    *value = file.readAll().trimmed().toULongLong(&ok);
+    return ok;
+}
+
+TrafficHistory::TrafficHistory(QObject *parent)
+    : QObject(parent)
+{
+    m_timer.setInterval(s_interval);
+    connect(&m_timer, &QTimer::timeout, this, &TrafficHistory::sample);
+    connect(NetworkManager::notifier(), &NetworkManager::Notifier::statusChanged, this, &TrafficHistory::updateTimer);
+    updateTimer();
+}
+
+QVariantMap TrafficHistory::download() const
+{
+    QVariantMap map;
+    for (const auto &[devicePath, history] : m_devices.asKeyValueRange()) {
+        map.insert(devicePath, QVariant::fromValue(history.download));
+    }
+    return map;
+}
+
+QVariantMap TrafficHistory::upload() const
+{
+    QVariantMap map;
+    for (const auto &[devicePath, history] : m_devices.asKeyValueRange()) {
+        map.insert(devicePath, QVariant::fromValue(history.upload));
+    }
+    return map;
+}
+
+void TrafficHistory::updateTimer()
+{
+    const auto status = NetworkManager::status();
+    const bool connected = status == NetworkManager::ConnectedLinkLocal || status == NetworkManager::ConnectedSiteOnly || status == NetworkManager::Connected;
+
+    if (connected && !m_timer.isActive()) {
+        m_timer.start();
+        sample();
+    } else if (!connected && m_timer.isActive()) {
+        m_timer.stop();
+        m_devices.clear();
+        Q_EMIT updated();
+    }
+}
+
+void TrafficHistory::sample()
+{
+    const qreal seconds = m_elapsed.isValid() ? m_elapsed.restart() / 1000.0 : 0;
+    if (!m_elapsed.isValid()) {
+        m_elapsed.start();
+    }
+
+    QHash<QString, DeviceHistory> devices;
+    for (const auto &device : NetworkManager::networkInterfaces()) {
+        if (device->state() != NetworkManager::Device::Activated) {
+            continue;
+        }
+
+        const QString statistics = u"/sys/class/net/%1/statistics/"_s.arg(device->ipInterfaceName());
+        quint64 rxBytes = 0;
+        quint64 txBytes = 0;
+        if (!readCounter(statistics + u"rx_bytes"_s, &rxBytes) || !readCounter(statistics + u"tx_bytes"_s, &txBytes)) {
+            continue;
+        }
+
+        auto it = m_devices.constFind(device->uni());
+        DeviceHistory history;
+        if (it == m_devices.constEnd()) {
+            history.download.fill(0, s_historyLength);
+            history.upload.fill(0, s_historyLength);
+        } else {
+            history = it.value();
+            const qreal download = seconds > 0 && rxBytes >= history.rxBytes ? (rxBytes - history.rxBytes) / seconds : 0;
+            const qreal upload = seconds > 0 && txBytes >= history.txBytes ? (txBytes - history.txBytes) / seconds : 0;
+            history.download.prepend(download);
+            history.download.removeLast();
+            history.upload.prepend(upload);
+            history.upload.removeLast();
+        }
+        history.rxBytes = rxBytes;
+        history.txBytes = txBytes;
+        devices.insert(device->uni(), history);
+    }
+
+    m_devices = devices;
+    Q_EMIT updated();
+}
+
+#include "moc_traffichistory.cpp"
diff --git a/libs/traffichistory.h b/libs/traffichistory.h
new file mode 100644
index 000000000..3b74152ce
--- /dev/null
+++ b/libs/traffichistory.h
@@ -0,0 +1,62 @@
+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: LGPL-2.1-only OR LGPL-3.0-only OR LicenseRef-KDE-Accepted-LGPL
+*/
+
+#ifndef PLASMA_NM_TRAFFIC_HISTORY_H
+#define PLASMA_NM_TRAFFIC_HISTORY_H
+
+#include <QElapsedTimer>
+#include <QHash>
+#include <QObject>
+#include <QTimer>
+#include <QVariantMap>
+
+#include <qqmlregistration.h>
+
+/**
+ * Keeps the recent download and upload speeds of every activated device,
+ * so that a speed graph can show them as soon as it is opened.
+ */
+class TrafficHistory : public QObject
+{
+    Q_OBJECT
+    QML_ELEMENT
+
+    /**
+     * Download speeds in bytes per second by device path, newest first
+     */
+    Q_PROPERTY(QVariantMap download READ download NOTIFY updated)
+
+    /**
+     * Upload speeds in bytes per second by device path, newest first
+     */
+    Q_PROPERTY(QVariantMap upload READ upload NOTIFY updated)
+
+public:
+    explicit TrafficHistory(QObject *parent = nullptr);
+
+    QVariantMap download() const;
+    QVariantMap upload() const;
+
+Q_SIGNALS:
+    void updated();
+
+private:
+    struct DeviceHistory {
+        quint64 rxBytes = 0;
+        quint64 txBytes = 0;
+        QList<qreal> download;
+        QList<qreal> upload;
+    };
+
+    void updateTimer();
+    void sample();
+
+    QHash<QString, DeviceHistory> m_devices;
+    QTimer m_timer;
+    QElapsedTimer m_elapsed;
+};
+
+#endif // PLASMA_NM_TRAFFIC_HISTORY_H
